// ?do_transform@?$collate@D@_STL@@MBE?AV?$basic_string@DV?$char_traits@D@_STL@@V?$allocator@D@2@@2@PBD0@Z
// partial score=0.988 date=2026-09-16
// cl: /O2 /EHsc /MD /D_STLP_USE_STATIC_LIB
// STLport 4.5.3

// The vtable at VA 0x0112EAD4 sits behind an RTTI complete object locator that
// spells '.?AV?$collate@D@_STL@@', and 0x0112EAE8 spells '.?AV?$collate@G@_STL@@'.
// vendor/stlport/stl/_collate.h declares do_compare, do_transform and do_hash in
// that order, and the landed do_compare and do_hash rows sit at slots 1 and 3 of
// both tables, so slot 2 is do_transform.  Each body zeroes the three members of
// the returned basic_string and then calls its range initializer, which is the
// string the STLport source builds from the two iterators it was handed.

typedef unsigned short wchar_t;

namespace _STL
{

struct input_iterator_tag {};
struct forward_iterator_tag : input_iterator_tag {};
struct bidirectional_iterator_tag : forward_iterator_tag {};
struct random_access_iterator_tag : bidirectional_iterator_tag {};

struct __false_type {};
struct __true_type {};

template <class T>
class allocator {};

template <class T>
class char_traits {};

template <class Pointer, class Value, class Alloc>
class _STLP_alloc_proxy
{
public:
	_STLP_alloc_proxy(const Alloc &, Pointer p) : _M_data(p) {}

	Pointer _M_data;
};

template <class T, class Alloc>
class _String_base
{
public:
	typedef allocator<T> allocator_type;

	_String_base(const allocator_type &a)
		: _M_start(0), _M_finish(0), _M_end_of_storage(a, (T *)0) {}

	~_String_base(void);

	T *_M_start;
	T *_M_finish;
	_STLP_alloc_proxy<T *, T, allocator_type> _M_end_of_storage;
};

template <class CharT, class Traits, class Alloc>
class basic_string : public _String_base<CharT, Alloc>
{
public:
	typedef allocator<CharT> allocator_type;

	__forceinline basic_string(const CharT *first, const CharT *last,
		const allocator_type &a = allocator_type())
		: _String_base<CharT, Alloc>(a)
	{
		_M_initialize_dispatch(first, last, __false_type());
	}

private:
	template <class InputIter>
	void _M_range_initialize(InputIter first, InputIter last,
		const forward_iterator_tag &tag);

	template <class InputIter>
	__forceinline void _M_range_initialize(InputIter first, InputIter last)
	{
		_M_range_initialize(first, last, random_access_iterator_tag());
	}

	template <class InputIter>
	__forceinline void _M_initialize_dispatch(InputIter first, InputIter last,
		const __false_type &notIntegral)
	{
		_M_range_initialize(first, last);
	}
};

class locale
{
public:
	class facet
	{
	protected:
		virtual ~facet();
	};
};

template <class CharT>
class collate : public locale::facet
{
public:
	typedef basic_string<CharT, char_traits<CharT>, allocator<CharT> > string_type;

protected:
	virtual ~collate();
	virtual string_type do_transform(const CharT *low, const CharT *high) const;
};

template <class CharT>
basic_string<CharT, char_traits<CharT>, allocator<CharT> >
collate<CharT>::do_transform(const CharT *low, const CharT *high) const
{
	return string_type(low, high);
}

template class collate<char>;
template class collate<wchar_t>;

} // namespace _STL
